#include <christmas_magic>
using namespace Phat_sincerity;

while (true) {
	Nga.feel() = {"Happy", "Pretty", "Studious"};
	Nga.with_family() = {"Cozy", "Warm", "Peaceful"};
	Nga.wish_list() = ALL_GOOD_THINGS;

	Phat.send_wish(Christmas, to:Nga);

	if (Nga.love() == 1) {
		Phat.stop_waiting();
		Phat.step_forward(to:Nga);
		return happiness::together_forever;
	} else {
		Phat.wait(forever, quietly:true, no_pressure:true);
		hope::Nga.give.a_chance->Phat.to_love;
	}
}

